'use strict';
// Supabase boundary. Unconfigured builds remain an explicitly labeled local preview.
const hubConfig=window.HubConfig||{};
const cloudEnabled=!!(hubConfig.supabaseUrl&&hubConfig.publishableKey);
let hubClient=null,cloudUser=null,cloudQuestions=[],cloudVersion=0,cloudReady=false,cloudBusy=false,cloudError='',cloudRecovery=false,cloudAuthMode='signin',cloudConflict=false,cloudPending=false,cloudSeq=0,cloudTimer,cloudSavePromise=null,cloudRestorePromise=null,cloudReturning=!cloudEnabled&&!!state.hubOnboardingCompleted,cloudWelcomeDismissed=false,cloudRole=null;
const cloudRenderBefore=render,cloudNavBefore=nav,cloudPersistBefore=persist,cloudSaveViewBefore=saveLastView,cloudProfileLinksBefore=profileLinks,cloudPrivacyBefore=privacyView,cloudAccessBefore=accessUI,cloudFeedbackBefore=feedbackView,cloudLeaderboardBefore=leaderboardView;
function blankHubState(){return {questions:[],saved:[],followed:[],votes:[],read:[],profile:{name:'',department:'',rank:'',email:'',photo:'',bio:'',country:'',experience:''},qaBadges:{},qaVisits:[],reports:[],feedback:[],questionUps:[],roundSupports:[],contributionMode:'answer',answerTopics:[],hubOnboardingCompleted:false,theme:'light',review:{track:null,session:null,history:[],records:{},flagged:[]}}}
function cloudCacheKey(){return 'hub-pending-v1:'+cloudUser.id}
function workspaceData(){const keys=['saved','followed','qaBadges','qaVisits','contributionMode','answerTopics','hubOnboardingCompleted','theme','review','lastView','lastSeen','hubTourCompleted'];return Object.fromEntries(keys.filter(k=>state[k]!==undefined).map(k=>[k,state[k]]))}
function cacheCloudWorkspace(){if(!cloudUser||!cloudReady)return false;try{cloudPending=true;cloudSeq++;localStorage.setItem(cloudCacheKey(),JSON.stringify({version:cloudVersion,data:workspaceData()}));clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>flushCloudWorkspace(),700);showCloudSync('Saving your progress…',true);return true}catch{showCloudSync('This device could not keep a recovery copy. Retry before leaving.',false,true);return false}}
globalThis.HubRuntime={enabled:cloudEnabled,cacheLocal:cacheCloudWorkspace,draftKey:()=>cloudUser?'hub-question-draft:'+cloudUser.id:'hub-question-draft:signed-out'};
function showCloudSync(text,busy=false,error=false){showWorkspaceStatus(text,busy,error);const s=document.querySelector('#cloudSyncState');if(s){s.textContent=text;s.className=error?'cloud-sync-error':''}}
async function flushCloudWorkspace(){if(!cloudPending)return true;if(cloudSavePromise)return cloudSavePromise;if(cloudConflict||!cloudUser)return false;clearTimeout(cloudTimer);cloudSavePromise=(async()=>{try{while(cloudPending){const seq=cloudSeq;const {data,error}=await hubClient.rpc('hub_save_workspace',{payload:workspaceData(),expected_version:cloudVersion});if(error)throw error;cloudVersion=data;if(seq===cloudSeq){cloudPending=false;localStorage.removeItem(cloudCacheKey())}else localStorage.setItem(cloudCacheKey(),JSON.stringify({version:cloudVersion,data:workspaceData()}));}showCloudSync('Progress saved.',false);return true}catch(e){if(e.code==='40001')cloudConflict=true;showCloudSync(cloudConflict?'Another device saved changes. Reload to reconcile; your recovery copy remains here.':'Not synced yet. Your recovery copy is on this device. Retry from Account & storage.',false,true);return false}finally{cloudSavePromise=null}})();return cloudSavePromise}
function cloudLoading(text){document.documentElement.dataset.cloud='ready';document.body.classList.add('cloud-auth');app.innerHTML=`<section class="cloud-loading" role="status" aria-live="polite"><span class="cloud-boat" aria-hidden="true">⚓</span><h1>${esc(text)}</h1><p>Keeping your place with the crew.</p></section>`}
async function cloudAction(button,text,action){if(cloudBusy)return false;cloudBusy=true;const old=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML=`<span class="cloud-button-spinner" aria-hidden="true"></span>${esc(text)}`}try{await action();return true}catch(e){toast(e.message||'Could not complete this action. Please retry.');showCloudSync(e.saved?'Saved; retrieving the updated discussion was interrupted. Retry to retrieve it.':'Not saved. Your entry is still here.',false,true);return false}finally{cloudBusy=false;if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=old}}}
async function cloudRows(table){let result=[];for(let from=0;from<20000;from+=1000){const{data,error}=await hubClient.from(table).select('*').order(table==='hub_profiles'?'id':table==='hub_question_votes'?'question_id':table==='hub_answer_votes'?'answer_id':'created_at').order(table==='hub_question_votes'||table==='hub_answer_votes'?'user_id':'id').range(from,from+999);if(error)throw error;result.push(...data);if(data.length<1000)return result}throw Error('This library needs paginated loading before more records can be displayed.');}
async function signedPhoto(path){if(!path)return '';const{data,error}=await hubClient.storage.from('hub-photos').createSignedUrl(path,3600);if(error)return '';return data.signedUrl}
async function loadCloudFeed(){const [qs,as,ps,qv,av]=await Promise.all(['hub_questions','hub_answers','hub_profiles','hub_question_votes','hub_answer_votes'].map(cloudRows));const profiles=new Map(ps.map(p=>[p.id,p]));const paths=[...new Set([...qs.flatMap(q=>q.photos),...as.flatMap(a=>a.photos),...ps.map(p=>p.photo)].filter(Boolean))];const urls=new Map(await Promise.all(paths.map(async p=>[p,await signedPhoto(p)])));const ownQVotes=new Set(qv.filter(v=>v.user_id===cloudUser.id).map(v=>v.question_id)),ownAVotes=new Set(av.filter(v=>v.user_id===cloudUser.id).map(v=>v.answer_id));state.questionUps=[...ownQVotes];state.votes=[...ownAVotes];cloudQuestions=qs.filter(q=>!q.hidden).map(q=>{const p=profiles.get(q.owner)||{};return{id:q.id,owner:q.owner,title:q.title,body:q.body,dept:q.department,equipment:q.equipment,tags:q.tags,photos:q.photos.map(p=>urls.get(p)).filter(Boolean),photoPaths:q.photos,author:p.name||'Seafarer',role:p.rank||'Crew member',status:q.status,outcome:q.outcome,accepted:q.accepted,time:new Date(q.created_at).toLocaleDateString(),createdAt:q.created_at,receivedUps:qv.filter(v=>v.question_id===q.id&&v.user_id!==cloudUser.id).length,answers:as.filter(a=>a.question_id===q.id&&!a.hidden).map(a=>{const ap=profiles.get(a.owner)||{};return{id:a.id,owner:a.owner,name:ap.name||'Seafarer',text:a.text,basis:a.basis,photos:a.photos.map(p=>urls.get(p)).filter(Boolean),photoPaths:a.photos,createdAt:a.created_at,help:av.filter(v=>v.answer_id===a.id&&v.user_id!==cloudUser.id).length}})}});state.questions=cloudQuestions;const me=profiles.get(cloudUser.id);if(me){state.profile={...me,email:cloudUser.email||'',photo:urls.get(me.photo)||'',photoPath:me.photo};}for(const t of cloudQuestions.map(q=>q.equipment))if(t&&!equipment.includes(t)){equipment.push(t);topicsByDepartment.General.push(t)}}
async function restoreCloud(user){if(cloudRestorePromise)return cloudRestorePromise;cloudRestorePromise=(async()=>{cloudReady=false;cloudUser=user;photos=[];answerPhotos=[];pendingProfileDraft=null;cloudError='';cloudConflict=false;cloudPending=false;cloudVersion=0;cloudLoading('Retrieving your workspace…');try{const {data,error}=await hubClient.from('hub_workspaces').select('data,version').eq('user_id',user.id).maybeSingle();if(error)throw error;state={...blankHubState(),...(data?.data||{})};cloudVersion=data?.version||0;const{data:profile,error:pe}=await hubClient.from('hub_profiles').select('id').eq('id',user.id).maybeSingle();if(pe)throw pe;if(!profile){const{error}=await hubClient.from('hub_profiles').insert({id:user.id});if(error)throw error}await loadCloudFeed();const{data:role}=await hubClient.from('hub_roles').select('role').eq('user_id',user.id).maybeSingle();cloudRole=role?.role||null;cloudReturning=!!state.hubOnboardingCompleted;cloudWelcomeDismissed=false;cloudReady=true;cloudRecoveryCopy=null;try{cloudRecoveryCopy=JSON.parse(localStorage.getItem(cloudCacheKey()))}catch{}if(cloudRecoveryCopy){cloudRecoveryView();return}finishCloudRestore()}catch(e){cloudError=e.message||'Could not retrieve your data.';cloudReady=false;render()}finally{cloudRestorePromise=null}})();return cloudRestorePromise}
let cloudRecoveryCopy=null;
function cloudRecoveryView(){app.innerHTML=`<section class="card cloud-auth-card"><h1>There’s unfinished saving on this device.</h1><p>A recovery copy was kept for this account. Your cloud records have been retrieved.</p><p>${cloudRecoveryCopy.version===cloudVersion?'The cloud version still matches. You can restore and sync this device’s progress.':'Another device has saved a newer version. Keep the cloud version to avoid overwriting it. Download your recovery copy first if needed.'}</p><div class="review-actions"><button class="btn" data-cloud="recoverDraft" ${cloudRecoveryCopy.version===cloudVersion?'':'disabled'}>Restore this device’s progress</button><button class="btn quiet" data-cloud="keepCloud">Use cloud version</button><button class="text-button" data-cloud="downloadDraft">Download recovery copy</button></div></section>`}
function finishCloudRestore(){document.body.classList.remove('cloud-auth');document.documentElement.dataset.cloud='ready';if(!state.hubOnboardingCompleted||!state.profile.name||!state.profile.rank||!state.profile.department){state.hubOnboardingCompleted=false;page='welcome'}else{page='home';restoreLastView()}render();if(state.hubOnboardingCompleted){state.lastSeen=new Date().toISOString();cacheCloudWorkspace();}scheduleCloudRefresh()}
let cloudRefreshTimer;
async function hubTimedFetch(input,init={}){const c=new AbortController(),abort=()=>c.abort();const timer=setTimeout(abort,20000);if(init.signal?.aborted)c.abort();init.signal?.addEventListener('abort',abort,{once:true});try{return await fetch(input,{...init,signal:c.signal})}finally{clearTimeout(timer);init.signal?.removeEventListener('abort',abort)}}
function scheduleCloudRefresh(){clearTimeout(cloudRefreshTimer);cloudRefreshTimer=setTimeout(async()=>{if(cloudUser&&cloudReady&&!cloudBusy&&!editingProfile&&!photos.length&&!answerPhotos.length&&['learn','progress'].includes(page)){try{await loadCloudFeed();render()}catch{showCloudSync('Unable to refresh discussions. Your current view is still available.',false,true)}}scheduleCloudRefresh()},50*60*1000)}
function cloudAuthView(){document.documentElement.dataset.cloud='ready';document.body.classList.add('cloud-auth');const reset=cloudAuthMode==='reset',signup=cloudAuthMode==='signup',password=cloudRecovery;app.innerHTML=`<section class="card cloud-auth-card"><img class="cloud-auth-mascot" src="assets/seafarer-mascot.webp" alt="Seafarer mascot"><div class="eyebrow">BULLETPROOF SEAFARER HUB</div><h1>${password?'Choose your new password.':reset?'Let’s get you back aboard.':signup?'Your experience belongs here.':'Welcome aboard.'}</h1><p>${password?'Set a new password for your account.':reset?'We’ll send a password reset link if this email has an account.':signup?'Ask, share experience, and keep useful answers within reach.':'Sign in to your questions, saved reads, and review progress.'}</p><form id="cloudAuthForm">${password?'':`<label class="field">Email<input name="email" type="email" required autocomplete="email" maxlength="254"></label>`}${reset?'':`<label class="field">Password<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="${signup||password?'new-password':'current-password'}"></label>`}${signup?`<label class="cloud-consent"><input type="checkbox" required> I agree to the <button type="button" class="text-button" data-cloud="terms">Terms</button> and have read the <button type="button" class="text-button" data-cloud="privacy">Privacy notice</button>.</label>`:''}<div id="hubCaptcha"></div><button class="btn" type="submit">${password?'Save new password':reset?'Send reset link':signup?'Create my account':'Sign in'} →</button><p id="authMessage" role="status"></p></form>${password?'':`<div class="cloud-auth-links"><button class="text-button" data-cloud="${reset||signup?'signin':'reset'}">${reset||signup?'Back to sign in':'Forgot password?'}</button>${hubConfig.registrationOpen?`<button class="text-button" data-cloud="${signup?'signin':'signup'}">${signup?'Already have an account?':'New here? Create an account'}</button>`:'<p class="hint">New account registration is not open yet.</p>'}</div>`}<p class="hint">Use only an account and device you trust. Your rank is self-reported.</p><button class="text-button" data-cloud="privacy">Privacy notice</button></section>`;document.querySelector('#cloudAuthForm').onsubmit=cloudAuthenticate;mountCloudCaptcha()}
let cloudCaptchaToken='',cloudCaptchaWidget=null;
function mountCloudCaptcha(){cloudCaptchaToken='';cloudCaptchaWidget=null;if(!hubConfig.turnstileSiteKey||cloudRecovery)return;const mount=()=>{if(!document.querySelector('#hubCaptcha')||cloudCaptchaWidget!==null)return;cloudCaptchaWidget=window.turnstile.render('#hubCaptcha',{sitekey:hubConfig.turnstileSiteKey,callback:t=>cloudCaptchaToken=t,'expired-callback':()=>cloudCaptchaToken=''})};if(window.turnstile)mount();else if(!document.querySelector('#turnstileScript')){const script=document.createElement('script');script.id='turnstileScript';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=mount;script.onerror=()=>toast('The security check could not load. Please reconnect and retry.');document.head.appendChild(script)}}
async function cloudAuthenticate(e){e.preventDefault();const f=e.target,d=new FormData(f),b=f.querySelector('button[type=submit]');await cloudAction(b,cloudRecovery?'Saving password…':'Connecting…',async()=>{let result;const options={captchaToken:cloudCaptchaToken};if(cloudRecovery){result=await hubClient.auth.updateUser({password:d.get('password')});if(result.error)throw result.error;cloudRecovery=false;const{data}=await hubClient.auth.getUser();if(data.user)await restoreCloud(data.user);return}if(hubConfig.turnstileSiteKey&&!cloudCaptchaToken)throw Error('Complete the security check first.');if(cloudAuthMode==='signup'){if(!hubConfig.registrationOpen)throw Error('Registration is not open.');result=await hubClient.auth.signUp({email:d.get('email'),password:d.get('password'),options:{...options,emailRedirectTo:location.origin+'/',data:{terms_version:'2026-10-17'}}})}else if(cloudAuthMode==='reset'){result=await hubClient.auth.resetPasswordForEmail(d.get('email'),{...options,redirectTo:location.origin+'/?recovery=1'})}else result=await hubClient.auth.signInWithPassword({email:d.get('email'),password:d.get('password'),options});if(result.error){if(window.turnstile&&cloudCaptchaWidget!==null)window.turnstile.reset(cloudCaptchaWidget);cloudCaptchaToken='';throw result.error}if(cloudAuthMode==='reset'||cloudAuthMode==='signup'&&!result.data.session){document.querySelector('#authMessage').textContent='Check your email for the next step. If a message is available for this address, it will arrive there.';return}if(result.data.user)await restoreCloud(result.data.user)})}
async function uploadCloudPhoto(data,pathHint){if(!data)return '';if(!data.startsWith('data:'))return pathHint||'';showCloudSync('Uploading your photo…',true);const blob=await(await fetch(data)).blob();if(!['image/jpeg','image/png','image/webp'].includes(blob.type)||blob.size>2097152)throw Error('Choose a JPEG, PNG, or WebP photo under 2 MB after resizing.');const ext=blob.type==='image/jpeg'?'jpg':blob.type==='image/png'?'png':'webp';const path=cloudUser.id+'/'+crypto.randomUUID()+'.'+ext;const{error}=await hubClient.storage.from('hub-photos').upload(path,blob,{contentType:blob.type,upsert:false});if(error)throw error;return path}
async function cloudInsertOnce(table,row){const{error}=await hubClient.from(table).insert(row);if(error&&error.code!=='23505')throw error;if(error){const{data,error:e}=await hubClient.from(table).select('*').eq('id',row.id).single();if(e||!data)throw error;for(const key of Object.keys(row))if(JSON.stringify(data[key])!==JSON.stringify(row[key]))throw Error('An earlier version of this entry was already posted. Refresh to open it; your current changes have not replaced it.')}}
function formRequestId(f){return f.dataset.requestId||(f.dataset.requestId=crypto.randomUUID())}
async function cloudPost(f,type){const d=Object.fromEntries(new FormData(f)),id=formRequestId(f);let uploads=[];f.hubUploads=f.hubUploads||new Map();for(const p of type==='question'?photos:answerPhotos){if(!f.hubUploads.has(p))f.hubUploads.set(p,await uploadCloudPhoto(p));uploads.push(f.hubUploads.get(p))};if(type==='question'){if(d.title.trim().length<8||d.body.trim().length<10)throw Error('Use at least 8 characters for the title and 10 for the description.');await cloudInsertOnce('hub_questions',{id,title:d.title.trim(),body:d.body.trim()+(d.model?.trim()?'\n\nEquipment model: '+d.model.trim():''),department:d.dept,equipment:d.equipment,tags:(d.tags||'').split(',').map(t=>t.trim()).filter(Boolean).slice(0,5),photos:uploads});}else{await cloudInsertOnce('hub_answers',{id,question_id:selected,text:d.text.trim(),basis:d.basis,photos:uploads})}try{await loadCloudFeed()}catch{const error=Error('Your post was saved, but the discussion could not refresh. Retry to retrieve it; it will not post twice.');error.saved=true;throw error}if(type==='question'){photos=[];sessionStorage.removeItem(questionDraftKey());selected=id;page='detail'}else answerPhotos=[];render();showCloudSync(type==='question'?'Question posted.':'Answer posted.')}
async function saveCloudProfile(f){const d=Object.fromEntries(new FormData(f));if(!d.name?.trim()||!d.rank?.trim()||!d.department)throw Error('Complete your name, rank, and department.');const photo=await uploadCloudPhoto(state.profile.photo,state.profile.photoPath);const fields={name:d.name.trim(),rank:d.rank.trim(),department:d.department,bio:d.bio||'',country:d.country||'',experience:d.experience||'',photo};const{error}=await hubClient.from('hub_profiles').update(fields).eq('id',cloudUser.id).select('id').single();if(error)throw error;state.profile={...state.profile,...fields,email:cloudUser.email,photoPath:photo,photo:photo?await signedPhoto(photo):''};const first=!state.hubOnboardingCompleted;state.hubOnboardingCompleted=true;pendingProfileDraft=null;editingProfile=false;if(!cacheCloudWorkspace()||!await flushCloudWorkspace())throw Error('Profile saved, but setup progress could not sync. Retry before continuing.');page=first?'home':'profile';render();showCloudSync('Profile saved.')}
function cloudDetailControls(){const q=all().find(q=>q.id===selected);if(!q)return;const resolve=document.querySelector('#resolve');if(resolve)resolve.onclick=async()=>{if(q.status==='Resolved'){await cloudAction(resolve,'Reopening…',async()=>{const{error}=await hubClient.from('hub_questions').update({status:'Open',outcome:''}).eq('id',q.id).select('id').single();if(error)throw error;await loadCloudFeed();render()});return}if(document.querySelector('#outcomeForm'))return;document.querySelector('#answerForm').insertAdjacentHTML('beforebegin','<form class="card" id="outcomeForm"><h2>Close the loop.</h2><label class="field">What happened?<textarea name="outcome" required minlength="3" maxlength="6000"></textarea></label><button class="btn" type="submit">Save reported outcome</button></form>');};const report=document.querySelector('#qaReport');if(report)report.onclick=()=>{document.querySelector('#qaReportArea').innerHTML='<form class="card" id="qaReportForm"><h2>Flag this discussion for review.</h2><label class="field">What needs checking?<textarea name="reason" required minlength="3" maxlength="1500"></textarea></label><button class="btn" type="submit">Send report</button></form>'}}
function cloudCleanCopy(){const top=document.querySelector('.topbar');const refresh=document.querySelector('#cloudRefreshButton');const refreshSafe=['learn','progress','leaderboard'].includes(page)||page==='home'&&state.contributionMode==='answer';if(refreshSafe&&!refresh)top.insertAdjacentHTML('beforeend','<button id="cloudRefreshButton" class="global-search-button" data-cloud="refresh" aria-label="Refresh shared discussions">↻ Refresh</button>');if(!refreshSafe&&refresh)refresh.remove();// Remove developer-only notices while retaining source/evidence and storage truth.
 for(const node of app.querySelectorAll('.banner,.qa-support,.shelf-footer,.qa-draft-note,.profile-email .hint'))if(/prototype|fictional|local test|browser.local|sample cases|live account verification/i.test(node.textContent))node.remove();
 for(const b of app.querySelectorAll('button'))if(/Post test question|Post test answer/.test(b.textContent))b.textContent=b.textContent.replace('test ','');
 for(const p of app.querySelectorAll('.hint,.qa-status,.qa-preview-tag,.qa-profile-title p')){if(p.textContent==='Saved to this browser only.')p.textContent='Shared with signed-in crew after posting.';if(/Photo changes are saved immediately/.test(p.textContent))p.textContent='Add a permitted photo. Save your profile when ready.';if(/Not shown on question cards/.test(p.textContent))p.textContent='Your email is private and managed by your account.';if(p.textContent==='SELF-REPORTED · LOCAL PROTOTYPE')p.textContent='SELF-REPORTED';}
 for(const n of app.querySelectorAll('p,small,span'))if(n.childElementCount===0){n.textContent=n.textContent.replace('Scores stay in this browser and do not affect the contributor leaderboard.','Practice progress is private to your account and does not affect contributor rankings.').replace('Local prototype badges. Counts above link to the original discussions, rather than repeating them here.','Your participation milestones link to the original discussions.').replace('Local preview only. Live points require other members’ reactions and server verification.','Points come from other members’ reactions and asker acceptance.').replace('SAMPLE ROUND','WEEKLY ROUND').replace('Rules are provisional for testing.','').replace('Prototype learning library','Review library').replace('FREE PROTOTYPE · VERSION 0.9','EARLY ACCESS · FREE FOR SEAFARERS').replace('Browser-local records. Shared accounts and cloud sync are not connected yet.','Your account keeps your contributions and private practice progress together.').replace('Your test votes stay in this browser.','Your votes are saved to your account.').replace('Local contribution preview','Your contributions').replace('Saved locally','Saved').replace('Flagging skips this question in future rounds on this browser. It does not send a report to JV yet.','Flagging skips this item in your future practice. Use Feedback if you want a moderator to check the answer key.').replace('questions flagged by you are skipped in future scored rounds.','questions flagged by you are skipped in future scored rounds.').replace(' skipped in future scored rounds; they do not send moderator reports.',' skipped in future scored rounds.');}
 const preview=app.querySelector('.welcome-preview-note');if(preview)preview.textContent='Your questions and answers will be shared with signed-in crew. Your email and review progress remain private. Review keys follow the supplied PDFs; check the source if an answer seems questionable.';
 const summaryEmail=app.querySelector('.profile-email strong');if(summaryEmail)summaryEmail.textContent='Email · private';
 const email=app.querySelector('#qaProfileForm input[name=email]');if(email){email.value=cloudUser.email;email.readOnly=true;email.setAttribute('aria-label','Account email (managed by sign-in)')}
 const emailNote=app.querySelector('.profile-email-note');if(emailNote)emailNote.textContent='Your account email stays private.';

 if(page==='community'&&/^https:\/\/(www\.)?facebook\.com\/groups\//.test(hubConfig.communityUrl)){app.querySelector('.community-panel').innerHTML='<h1>Join the crew on Facebook.</h1><p>Help shape the Hub with feedback and updates.</p><a class="btn" target="_blank" rel="noopener noreferrer" href="'+esc(hubConfig.communityUrl)+'">Open Facebook community ↗</a>';}const stage=app.querySelector('.demo');if(stage)stage.textContent='Crew Hub';
 if(page==='detail')cloudDetailControls();
 if(page==='profile'){const photo=document.querySelector('#qaProfilePhoto');if(photo)photo.onchange=async e=>{const arr=[];await addPhotos(e.target.files,arr,1);if(arr[0]){state.profile.photo=arr[0];render()}};const remove=document.querySelector('#removeProfilePhoto');if(remove)remove.onclick=()=>{state.profile.photo='';state.profile.photoPath='';render()};}
}
profileLinks=function(){if(!cloudEnabled)return cloudProfileLinksBefore();return cloudProfileLinksBefore()+`<section class="card"><button class="profile-action" data-nav="access"><span>Account & sync</span><small>Open →</small></button>${cloudRole?'<button class="profile-action" data-cloud="moderation"><span>Moderator queue</span><small>Open →</small></button>':''}</section>`};
accessUI=function(){if(!cloudEnabled){cloudAccessBefore();return}app.innerHTML=`<button class="back" data-nav="settings">← Settings & support</button><header class="ui-page-head"><div class="eyebrow">YOUR ACCOUNT</div><h1>Your place with the crew.</h1><p>${esc(cloudUser.email)}</p></header><section class="card"><h2>Cloud progress</h2><p id="cloudSyncState">${cloudPending?'Changes are waiting to sync.':'Your last save is synced.'}</p><p class="hint">Questions, answers, and profile details are stored in your account. Review progress, saved reads, and preferences are private. Unsynced progress has a recovery copy on this device.</p><div class="review-actions"><button class="btn" data-cloud="retrySync">Retry saving</button><button class="btn quiet" data-cloud="refresh">Refresh discussions</button></div></section><section class="card"><h2>Account controls</h2><button class="text-button" data-cloud="sendReset">Send a password reset email</button><p><button class="btn quiet" data-cloud="logout">Sign out</button></p><div id="logoutChoice"></div></section>`};
privacyView=function(){if(!cloudEnabled){cloudPrivacyBefore();return}app.innerHTML=`<button class="back" data-nav="settings">← Settings</button><article class="card privacy-copy"><div class="eyebrow">PRIVACY NOTICE</div><h1>Your information, explained.</h1><p>Bulletproof Seafarer Hub is operated by JV Ursal / Bulletproof Seafarers. Privacy contact: ${esc(hubConfig.privacyContact||'Not configured; registration is closed.')}</p><h2>What is shared</h2><p>Your name, self-reported rank, department, bio, experience, country, and profile photo can be read by signed-in members. Posted questions, answers, photos, reactions, and outcomes are shared with signed-in members. Do not post confidential vessel, company, location, or personal information.</p><h2>What stays private</h2><p>Your email and authentication records are managed by Supabase Auth. Saved discussions, review attempts, practice scores, preferences, and your last view are stored under your account with access controls. Reports and feedback are readable by authorized moderators.</p><h2>Storage and providers</h2><p>Cloudflare serves the website and may process security/access logs. Supabase processes account, database, and photo storage. Their policies and the project’s configured hosting regions apply. The browser retains a sign-in session and recovery copies of unsynced personal progress. It is not a secure document vault.</p><h2>Retention and your choices</h2><p>Account records remain while the account is active unless removed during moderation or through a deletion request. Contact the operator to request access, corrections, or deletion. Shared discussions may need anonymization to preserve context. Provider backups and logs may remain for their configured retention periods; ask the operator for those details. Signing out does not delete shared posts. Clearing browser data removes device recovery copies, not cloud records.</p><h2>Optional features</h2><p>Review scores are for personal practice, not certification. Facebook opens separately and receives no automatic transfer of your local profile. No advertising tracker or push notifications are implemented.</p><p class="hint">This notice describes the implemented design. Before public registration, the operator must verify actual regions, retention settings, privacy contact, and request handling against the configured services.</p></article>`};
function cloudTerms(){app.innerHTML=`<article class="card privacy-copy"><button class="back" data-cloud="signin">← Sign in</button><h1>Participate with care.</h1><p>This free Hub helps seafarers exchange experience and review questions. It does not replace vessel procedures, official training, manuals, responsible officers, or emergency support.</p><p>Post only content you have permission to share. No confidential documents, personal attacks, spam, or unsafe instructions. Clearly distinguish observations, firsthand experience, and suggestions. Moderators may hide content and review reports.</p><p>Rank and experience are self-reported. Popular answers, badges, and practice scores do not establish technical competence or correctness. Review keys follow the supplied source copies and may contain mistakes.</p><p>You remain responsible for the information you post. You allow the Hub to display it to signed-in members as part of the relevant discussion. Contact ${esc(hubConfig.privacyContact||'the operator')} about your content or account.</p></article>`}
feedbackView=function(){cloudFeedbackBefore();if(!cloudEnabled)return;const f=app.querySelector('#profileFeedbackForm');if(f){const hint=f.querySelector('p.hint');if(hint)hint.textContent='Sent to the app’s moderator queue. Do not include confidential information.';const b=f.querySelector('button');if(b)b.textContent='Send feedback'}};
async function cloudModeration(){if(!cloudRole)return;cloudLoading('Retrieving reports…');try{const reports=await cloudRows('hub_reports'),feedback=await cloudRows('hub_feedback');document.body.classList.remove('cloud-auth');app.innerHTML=`<button class="back" data-nav="profile">← Profile</button><h1>Moderator queue</h1><p class="hint">Visibility changes require a reason and are recorded on the server.</p>${reports.map(r=>`<section class="card"><h2>Reported discussion</h2><p>${esc(r.reason)}</p><p class="hint">${esc(r.created_at)}</p><button class="text-button" data-open="${r.question_id}">Open discussion →</button><form class="cloudModerateForm"><input name="target" type="hidden" value="${r.question_id}"><label class="field">Reason<textarea required name="reason" minlength="3"></textarea></label><button class="btn" name="hide" value="true">Hide question</button><button class="btn quiet" name="hide" value="false">Restore question</button></form></section>`).join('')||'<p>No reports yet.</p>'}<h2>App feedback</h2>${feedback.map(f=>`<article class="card"><strong>${esc(f.topic)}</strong><p>${esc(f.message)}</p></article>`).join('')||'<p>No feedback yet.</p>'}`;for(const f of app.querySelectorAll('.cloudModerateForm'))f.onsubmit=async e=>{e.preventDefault();await cloudAction(e.submitter,'Saving…',async()=>{const{error}=await hubClient.rpc('hub_moderate',{kind:'question',target:f.elements.target.value,hide:e.submitter.value==='true',reason:f.elements.reason.value});if(error)throw error;await loadCloudFeed();toast('Visibility updated.');})}}catch(e){cloudError=e.message;render()}}
function cloudTourCard(){if(state.hubTourCompleted||page!=='home')return;app.insertAdjacentHTML('afterbegin',`<section class="card cloud-start"><div class="eyebrow">YOUR FIRST STEPS</div><h2>Start with what you need today.</h2><p>Use <strong>Ask</strong> to describe a problem, or <strong>Answer</strong> to choose topics you can help with. Open <strong>Library</strong> to find an existing discussion. The navigation stays at the bottom on your phone.</p><div class="review-actions"><button class="btn quiet" data-nav="help">Show me around →</button><button class="text-button" data-cloud="dismissTour">Got it—I'm ready</button></div></section>`)}
function cloudReturnCard(){if(!cloudReturning||cloudWelcomeDismissed||!state.hubOnboardingCompleted||!['home','learn','progress','review'].includes(page))return;app.insertAdjacentHTML('afterbegin',`<aside class="cloud-return card"><div><span class="eyebrow">WELCOME BACK, ${esc(qProfileName().split(' ')[0])}</span><h2>Good to have you aboard again.</h2><p>${!cloudEnabled?'Your saved progress on this device is ready.':state.review.session&&!state.review.session.done?'Your unfinished review round is ready when you are.':`${all().filter(q=>!q.answers.length).length} questions are waiting for shared experience. One useful contribution is enough to start.`}</p><button class="text-button" data-nav="${state.review.session&&!state.review.session.done?'review':'home'}">${state.review.session&&!state.review.session.done?'Continue reviewing':'Find a question to answer'} →</button></div><button class="cloud-dismiss" data-cloud="dismissWelcome" aria-label="Dismiss welcome-back message">×</button></aside>`)}
render=function(){if(!cloudEnabled){cloudRenderBefore();if(state.hubOnboardingCompleted){cloudReturnCard();cloudTourCard()}return}if(!cloudUser||cloudRecovery){cloudAuthView();return}if(!cloudReady){if(cloudError){document.body.classList.add('cloud-auth');app.innerHTML=`<section class="card cloud-auth-card"><h1>We couldn’t retrieve your workspace.</h1><p>${esc(cloudError)}</p><p>Your cloud records have not been replaced.</p><button class="btn" data-cloud="restore">Retry retrieving</button><button class="text-button" data-cloud="forceLogout">Sign out</button></section>`}else cloudLoading('Retrieving your workspace…');return}if(cloudRecoveryCopy){cloudRecoveryView();return}document.body.classList.remove('cloud-auth');cloudRenderBefore();cloudCleanCopy();cloudReturnCard();cloudTourCard()};
persist=function(){if(!cloudEnabled)return cloudPersistBefore();if(!cloudReady)return false;awardQABadges();return cacheCloudWorkspace()};
saveLastView=function(){if(!cloudEnabled)return cloudSaveViewBefore();if(!cloudReady||!state.hubOnboardingCompleted)return false;const v={page,selected:page==='detail'?selected:null,shelfTopic,shelfFileQuery,shelfTopicQuery,shelfStatus,shelfReturn,qaView,qaDepartment,query,topic,sort,scrollY:window.scrollY||0};if(JSON.stringify(v)!==JSON.stringify(state.lastView)){state.lastView=v;cacheCloudWorkspace()}return true};
nav=function(p){if(cloudEnabled&&(!cloudUser||!cloudReady||cloudRecovery)){render();return}cloudNavBefore(p);if(cloudEnabled&&cloudReady)showCloudSync(cloudPending?'Saving your progress…':'Your place is saved.',cloudPending)};
// Capture writes before legacy local handlers; no cloud write trusts a display name.
document.addEventListener('submit',e=>{if(!cloudEnabled||!cloudReady||!cloudUser)return;const f=e.target;if(!['askForm','answerForm','qaProfileForm','outcomeForm','qaReportForm','profileFeedbackForm'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();cloudAction(e.submitter||f.querySelector('button[type=submit],button.btn'),'Saving…',async()=>{if(f.id==='askForm'||f.id==='answerForm')return cloudPost(f,f.id==='askForm'?'question':'answer');if(f.id==='qaProfileForm')return saveCloudProfile(f);const d=Object.fromEntries(new FormData(f));if(f.id==='outcomeForm'){const{error}=await hubClient.from('hub_questions').update({status:'Resolved',outcome:d.outcome.trim()}).eq('id',selected).select('id').single();if(error)throw error;await loadCloudFeed();render()}else if(f.id==='qaReportForm'){await cloudInsertOnce('hub_reports',{id:formRequestId(f),question_id:selected,reason:d.reason.trim()});f.innerHTML='<p role="status">Report sent for moderator review. Thank you.</p>'}else{await cloudInsertOnce('hub_feedback',{id:formRequestId(f),message:d.message.trim(),topic:d.topic});f.innerHTML='<p role="status">Feedback sent. Thank you for helping improve the Hub.</p>'}})},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(!cloudEnabled){if(d.cloud==='dismissTour'||d.cloud==='dismissWelcome'){e.preventDefault();e.stopImmediatePropagation();if(d.cloud==='dismissTour'){state.hubTourCompleted=true;persist()}else cloudWelcomeDismissed=true;render()}return;}if(d.cloud){e.preventDefault();e.stopImmediatePropagation();cloudHandle(d.cloud,b);return}if(!cloudReady)return;if(d.vote||d.questionUp||d.accept||d.profileSupport){e.preventDefault();e.stopImmediatePropagation();cloudAction(b,'Saving…',async()=>{if(d.profileSupport){const c=cloudBoard?.candidates.find(c=>c.id===d.profileSupport);if(!c)throw Error('This profile is not in the current shortlist.');const r=c.supported?await hubClient.from('hub_support').delete().eq('week',cloudBoard.week).eq('candidate',c.id).eq('voter',cloudUser.id):await hubClient.from('hub_support').insert({week:cloudBoard.week,candidate:c.id});if(r.error)throw r.error;cloudBoard=null;await fetchCloudBoard();render();return}if(d.accept){const{error}=await hubClient.from('hub_questions').update({accepted:d.accept}).eq('id',selected).select('id').single();if(error)throw error}else{const answer=!!d.vote,id=d.vote||d.questionUp,table=answer?'hub_answer_votes':'hub_question_votes',field=answer?'answer_id':'question_id',already=(answer?state.votes:state.questionUps).includes(id);const result=already?await hubClient.from(table).delete().eq(field,id).eq('user_id',cloudUser.id):await hubClient.from(table).insert({[field]:id});if(result.error)throw result.error}await loadCloudFeed();render()});}},true);
async function cloudHandle(action,b){if(action==='dismissTour'){state.hubTourCompleted=true;persist();render();return}if(['signin','signup','reset'].includes(action)){cloudAuthMode=action;cloudRecovery=false;render();return}if(action==='privacy'){privacyView();app.insertAdjacentHTML('afterbegin','<button class="back" data-cloud="signin">← Sign in</button>');return}if(action==='terms'){cloudTerms();return}if(action==='dismissWelcome'){cloudWelcomeDismissed=true;render();return}if(action==='recoverDraft'){Object.assign(state,cloudRecoveryCopy.data);cloudRecoveryCopy=null;finishCloudRestore();cacheCloudWorkspace();await flushCloudWorkspace();return}if(action==='keepCloud'){localStorage.removeItem(cloudCacheKey());cloudRecoveryCopy=null;finishCloudRestore();return}if(action==='downloadDraft'){const url=URL.createObjectURL(new Blob([JSON.stringify(cloudRecoveryCopy,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='hub-progress-recovery.json';a.click();URL.revokeObjectURL(url);return}if(action==='restore'){await restoreCloud(cloudUser);return}if(action==='moderation'){await cloudModeration();return}await cloudAction(b,action==='refresh'?'Retrieving discussions…':'Saving…',async()=>{if(action==='retrySync'){if(cloudConflict)throw Error('Reload before reconciling a newer cloud version. Your device recovery copy is kept.');if(!await flushCloudWorkspace())throw Error('Still not synced. Your recovery copy is on this device.');return}if(action==='refresh'){await loadCloudFeed();render();showCloudSync('Discussions refreshed.');return}if(action==='sendReset'){const{error}=await hubClient.auth.resetPasswordForEmail(cloudUser.email,{redirectTo:location.origin+'/?recovery=1'});if(error)throw error;toast('Check your email for a reset link.');return}if(action==='logout'||action==='forceLogout'){const draftKey=questionDraftKey();if(action==='logout'&&!await flushCloudWorkspace()){document.querySelector('#logoutChoice').innerHTML='<p>Your progress has not synced. A recovery copy is kept on this device.</p><button class="text-button" data-cloud="forceLogout">Sign out anyway</button>';return}const{error}=await hubClient.auth.signOut({scope:'local'});if(error){if(action!=='forceLogout')throw error;localStorage.removeItem('hub-auth-v1');localStorage.removeItem('hub-auth-v1-code-verifier');location.replace(location.origin+'/');return;}cloudUser=null;cloudReady=false;state=blankHubState();cloudQuestions=[];photos=[];answerPhotos=[];pendingProfileDraft=null;sessionStorage.removeItem(draftKey);clearTimeout(cloudTimer);clearTimeout(cloudRefreshTimer);render()}})}
let cloudBoard=null,cloudBoardLoading=false,cloudBoardError='';
async function fetchCloudBoard(){if(cloudBoardLoading)return;cloudBoardLoading=true;cloudBoardError='';try{const{data,error}=await hubClient.rpc('hub_get_leaderboard');if(error)throw error;cloudBoard=data}catch(e){cloudBoardError=e.message}finally{cloudBoardLoading=false}}
leaderboardView=function(){if(!cloudEnabled){cloudLeaderboardBefore();return}if(!cloudBoard){app.innerHTML='<button class="back" data-nav="progress">← Progress</button><h1>Top seafarers</h1><p role="status">'+(cloudBoardError?esc(cloudBoardError):'Retrieving this week’s contributors…')+'</p>';if(!cloudBoardLoading&&!cloudBoardError)fetchCloudBoard().then(()=>{if(page==='leaderboard')render()});return}app.innerHTML=`<button class="back" data-nav="progress">← Progress</button><header class="ui-page-head"><div class="eyebrow">CONTRIBUTIONS EARN THE SPOT</div><h1>Top seafarers</h1><p>Weekly shortlist · ${esc(cloudBoard.week)} · Monday cutoff, UTC</p></header><details class="review-notes"><summary>How this week’s ranking works</summary><p>Points earned before Monday qualify up to ten contributors. A question upvote earns 1 point, a Helpful answer vote earns 2, and asker acceptance earns 5 for another person’s answer. Posting alone and self-votes earn no points.</p><p>The shortlist stays fixed for the week. Member support votes rank those eligible profiles; ties use qualifying points, then a stable account ID. Support can be removed. The next week gets a new shortlist and fresh support votes.</p><p>Recognition is for participation, not technical qualifications or verified advice.</p></details>${cloudBoard.candidates.map((c,i)=>`<article class="card cloud-rank-row"><span class="rank-pos">${i+1}</span><div class="rank-person"><h2>${esc(c.name)}</h2><p>${esc(c.rank)} · ${esc(c.department)}</p><span class="tag">${c.points} qualifying points</span></div><button class="btn quiet" data-profile-support="${c.id}" aria-pressed="${c.supported}" ${c.id===cloudUser.id?'disabled':''}>${c.supported?'✓ Supported':'↑ Support'} · ${c.votes}</button></article>`).join('')||'<section class="card"><h2>The first shortlist is ahead of us.</h2><p>Contribute useful questions and answers this week. Points from other members qualify contributors for the next Monday’s shortlist.</p><button class="btn" data-nav="home">Find a question →</button></section>'}`};
if(cloudEnabled){
 all=()=>cloudQuestions;own=q=>!!cloudUser&&q.owner===cloudUser.id;ownAnswer=a=>!!cloudUser&&a.owner===cloudUser.id;
 hubClient=window.supabase.createClient(hubConfig.supabaseUrl,hubConfig.publishableKey,{global:{fetch:hubTimedFetch},auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'hub-auth-v1'}});
 hubClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){cloudRecovery=true;cloudUser=session?.user||null;render()}if(event==='SIGNED_OUT'){cloudRecovery=false;cloudUser=null;cloudReady=false;state=blankHubState();cloudQuestions=[];render()}if(event==='SIGNED_IN'&&session?.user&&!cloudReady&&!cloudRecovery)setTimeout(()=>restoreCloud(session.user),0)});
 (async()=>{cloudLoading('Finding your place…');const sessionResult=await hubClient.auth.getSession();const{data,error}=await hubClient.auth.getUser();if(error&&sessionResult.data?.session&&!cloudRecovery){cloudUser=sessionResult.data.session.user;cloudError='Your connection could not be verified. Reconnect and retry retrieving your workspace.';render();return}if(data.user&&!cloudRecovery)await restoreCloud(data.user);else render()})();
 window.addEventListener('online',()=>{if(cloudPending&&!cloudConflict)flushCloudWorkspace()});window.addEventListener('beforeunload',e=>{if(cloudPending){e.preventDefault();e.returnValue=''}});
}else render();
